def compute(vars):
    shares_repurchase_amount = vars["v1"]
    total_authorized_amount = vars["v2"]

    if total_authorized_amount == 0:
        value = None
    else:
        value = (shares_repurchase_amount / total_authorized_amount) * 100

    return {
        "value": value,
        "trace": {
            "shares_repurchase_amount": shares_repurchase_amount,
            "total_authorized_amount": total_authorized_amount,
            "ratio": None if total_authorized_amount == 0 else shares_repurchase_amount / total_authorized_amount,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
